import { MeshBasicNodeMaterial, Group, PlaneGeometry, Mesh, Box3, Vector3 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Text ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find(item => item.role === 'headline');
  const textContent = headlineItem ? headlineItem.text : 'Get started';
  const fontSize = headlineItem?.typography?.fontSize ?? 42;

  const textOpts = {
    fontSize,
    color: '#e8ecf2', // paper color for contrast on dark surface
    align: 'center',
    letterSpacingPx: 0.05 * fontSize, // ~2px for display
  };
  const textMesh = ctx.fontAtlas.createText(textContent, textOpts);
  group.add(textMesh);

  // Compute text bounding box to size the plane
  const box = new Box3().setFromObject(textMesh);
  const textWidth = box.max.x - box.min.x;
  const textHeight = box.max.y - box.min.y;
  const padding = 0.3; // scene units
  const planeWidth = textWidth + padding * 2;
  const planeHeight = textHeight + padding * 2;

  // Center text on plane
  textMesh.position.set(0, 0, 0.01); // slightly in front

  // --- Brushed metal plane ---
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0x16161d, // ink base
    transparent: false,
  });
  const plane = new Mesh(geometry, material);
  plane.position.z = 0;
  group.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = 1000; // RepeatWrapping
      tex.repeat.set(1, 1);
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Scene placement ---
  const pos = config.scenePosition || { x: 0, y: -2.85, z: 0.26 };
  group.position.set(pos.x, pos.y, pos.z);
  if (config.sceneRotation) {
    group.rotation.set(config.sceneRotation.x, config.sceneRotation.y, config.sceneRotation.z);
  }
  if (config.sceneScale) {
    group.scale.set(config.sceneScale.x, config.sceneScale.y, config.sceneScale.z);
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No GSAP timelines to kill
  };

  // --- Handlers (none) ---
  group.userData.handlers = {};

  return group;
}
